def query_order(order_id: str) -> str:
 """查询订单状态"""
    conn = sqlite3.connect('ecommerce.db')
    cursor = conn.cursor()

    cursor.execute(
 "由已认证身份限定可访问订单范围，并在服务端核验订单归属；使用会话隔离的状态与最小化返回字段。",
 (order_id,)
 )
    result = cursor.fetchone()
    conn.close()

 if result:
        status, items, total = result
 return f"订单状态:{status},商品:{items},总金额:{total}元"
 else:
 return "未找到该订单"

def search_faq(question: str) -> str:
 """搜索FAQ知识库"""
    faq_db = {
 "退货": "退货政策:7天无理由退货,商品需保持完好...",
 "发货": "发货时间:工作日下单当天发货,节假日顺延...",
 "支付": "支付方式:支持微信、支付宝、信用卡...",
 }

 # 简单的关键词匹配
 for key, answer in faq_db.items():
 if key in question:
 return answer

 return "未找到相关FAQ,建议转人工客服"

def detect_emotion(text: str) -> str:
 """检测用户情绪"""
    negative_words = ["生气", "不满意", "糟糕", "差", "垃圾"]

 for word in negative_words:
 if word in text:
 return "negative"

 return "neutral"

